/// Lua helpers every case body can call (defined before the body, inside the pcall).
const TRB_HELPERS: &str = r#"
local function findUnique(title)
	for _, list in pairs(data.uniques) do
		for _, raw in ipairs(list) do
			if raw:match("^%s*([^\n]+)") == title then
				return raw:gsub("^%s+", "")
			end
		end
	end
	error("no unique " .. title)
end
local function equip(raw)
	build.itemsTab:CreateDisplayItemFromRaw(raw)
	build.itemsTab:AddDisplayItem()
	runCallback("OnFrame")
end
local function equipUnique(title)
	equip("Rarity: UNIQUE\n" .. findUnique(title))
end
local function paste(text)
	build.skillsTab:PasteSocketGroup(text)
	runCallback("OnFrame")
end
local function selectMain(name)
	for gi, g in ipairs(build.skillsTab.socketGroupList) do
		for si, s in ipairs(g.displaySkillList or { }) do
			if s.activeEffect.grantedEffect.name == name then
				build.mainSocketGroup = gi
				g.mainActiveSkill = si
				g.mainActiveSkillCalcs = si
				build.modFlag = true
				build.buildFlag = true
				runCallback("OnFrame")
				return
			end
		end
	end
	error("no skill " .. name)
end
"#;

